"""EP02 cinematic 16:9 version (RU + EN) and the scene breakdown document.
All times are VOICE times as L(ru, en); the build shifts them by OFF (alarm pre-roll).
Outputs: config/timeline.ep02_ru.json, config/timeline.ep02_en.json, docs/EP02_scenario_{ru,en}.md"""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OFF = 1.2

class L(tuple):
    def __new__(cls, ru, en): return tuple.__new__(cls, (ru, en))
class T2(tuple):
    def __new__(cls, ru, en): return tuple.__new__(cls, (ru, en))
def pick(o, i, shift=True):
    if isinstance(o, L): return round(o[i] + (OFF if shift else 0), 3)
    if isinstance(o, T2): return o[i]
    if isinstance(o, dict): return {k: pick(v, i, shift) for k, v in o.items()}
    if isinstance(o, list): return [pick(v, i, shift) for v in o]
    return o
def kf(*pts): return [[t, x, y, z] for t, x, y, z in pts]

TR = [json.load(open(os.path.join(ROOT, 'config', f'ep02_transcript_{l}.json'))) for l in ('ru', 'en')]
LAST_END = [TR[i][-1]['words'][-1]['e'] for i in (0, 1)]

S = []
def scene(n, title, type_, start, doc, sfx, **kw): S.append(dict(n=n, title=title, type=type_, start=start, doc=doc, sfx=sfx, **kw))

