def words_between(i, a, b):
    out = []
    for seg in TR[i]:
        for w in seg['words']:
            if a <= w['s'] < b: out.append(w['w'].strip())
    return ' '.join(out)

def build(i):
    lang = ('ru', 'en')[i]
    shots = []
    for s in S:
        d = {k: v for k, v in s.items() if k not in ('doc', 'sfx', 'title', 'n')}
        d = pick(d, i)
        d['id'] = f"{s['n']:02d}"
        if 'inT' in d: d['in'] = d.pop('inT')
        shots.append(d)
    cut = round(LAST_END[i] + OFF + 0.25, 3)
    for a, b in zip(shots, shots[1:]): a['end'] = b['start']
    shots[0]['start'] = 0.0; shots[-1]['end'] = round(cut + 2.0, 3)
    st = {s['id']: s['start'] for s in shots}
    g = lambda x: pick(x, i)
    # sound events
    ev = [{'t': 0.0, 'type': 'roomtone', 'until': cut}, {'t': 0.0, 'type': 'alarmclock', 'dur': OFF + 0.9}]
    ev += [{'t': st['02'] - 0.4, 'type': 'steps', 'dur': 2.6}, {'t': g(S[2]['openAt']), 'type': 'tapclick'}]
    ev += [{'t': g(t), 'type': 'tapclick'} for t in S[3]['hardAt']]
    ev += [{'t': st['06'] - 0.2, 'type': 'steps', 'dur': 2.2}, {'t': g(S[5]['tapAt']), 'type': 'tapclick'}, {'t': g(S[5]['showerAt']), 'type': 'tapclick'},
           {'t': g(S[6]['screen']['notifs'][0]['at']), 'type': 'ping'}, {'t': st['08'] - 0.2, 'type': 'steps', 'dur': 2.0},
           {'t': st['09'], 'type': 'flow', 'dur': st['10'] - st['09']}, {'t': st['10'], 'type': 'hit', 'gain': -3},
           {'t': st['10'], 'type': 'wind', 'dur': st['13'] - st['10']}, {'t': st['13'], 'type': 'click'}, {'t': st['13'] + 0.3, 'type': 'jingle'},
           {'t': st['13'] + 0.5, 'type': 'tvhum', 'dur': st['14'] - st['13'] - 0.5}, {'t': g(S[12]['worldAt']), 'type': 'alarm'}]
    ev += [{'t': g(it['at']), 'type': 'tick'} for it in S[13]['items']] + [{'t': g(S[13]['items'][-1]['at']), 'type': 'hit', 'gain': -1}]
    ev += [{'t': st['15'], 'type': 'wind', 'dur': st['16'] - st['15']}, {'t': st['15'] + 1.0, 'type': 'creak'},
           {'t': st['16'], 'type': 'crowd', 'dur': st['17'] - st['16']}, {'t': st['16'], 'type': 'steps', 'dur': st['17'] - st['16'], 'fast': 1},
           {'t': g(S[15]['emptyAt']), 'type': 'hit', 'gain': -6}, {'t': st['18'], 'type': 'wind', 'dur': st['20'] - st['18']},
           {'t': st['19'], 'type': 'crowd', 'dur': st['20'] - st['19']}]
    ev += [{'t': g(S[18]['flashFrom']) + k * 0.9, 'type': 'shutter'} for k in range(4)]
    ev += [{'t': st['20'], 'type': 'steps', 'dur': 3.0, 'dry': 1}, {'t': st['20'], 'type': 'wind', 'dur': st['21'] - st['20']}, {'t': g(S[19]['openAt']), 'type': 'creak'}]
    ev += [{'t': g(k), 'type': 'uknock'} for k in S[20]['knocks']]
    ev += [{'t': g(S[21]['flashAt']), 'type': 'click'}, {'t': g(S[22]['vibAt']), 'type': 'vibrate', 'n': 2},
           {'t': g(S[22]['screen']['notifs'][0]['at']), 'type': 'alert'}, {'t': g(S[22]['red']), 'type': 'hit', 'gain': -2}]
    ev.sort(key=lambda e: e['t'])
    # music: gradually more tense, hard cut after the last question
    mus = [(0, 0.15), (st['03'], 0.25), (g(S[2]['openAt']), 0.05), (st['05'], 0.3), (st['06'], 0.4), (st['08'], 0.55), (st['09'], 0.5),
           (st['10'], 0.75), (st['12'], 0.7), (st['13'], 0.5), (st['14'], 0.9), (st['15'], 0.85), (st['16'], 0.95), (st['17'], 0.4),
           (st['18'], 0.55), (st['20'], 0.6), (st['21'] - 0.3, 0.1), (st['22'], 0.5), (st['23'], 0.85), (st['24'], 0.9), (cut - 0.02, 1.0), (cut, 0.0)]
    chords = [[0.0, st['06'] + 0.4, [41, 48, 53, 57]], [st['06'], st['10'] + 0.4, [38, 45, 52, 53]], [st['10'], st['14'] + 0.4, [38, 46, 52, 57]],
              [st['14'], st['17'] + 0.4, [34, 41, 50, 53]], [st['17'], st['20'] + 0.4, [33, 40, 49, 52]], [st['20'], cut + 0.2, [31, 38, 46, 50]]]
    tl = {
      '_comment': 'EP02 cinematic 16:9. Generated by tools/make_ep02_cine.py — see docs/EP02_scenario_*.md for the scene breakdown.',
      'fps': 30, 'width': 1920, 'height': 1080, 'duration': shots[-1]['end'], 'outName': f'WhatIf_EP02_{lang}',
      'voice': f'assets/audio/ep02_voice_{lang}.mp3', 'voiceOffset': OFF, 'strings': f'config/strings.{lang}.json',
      'shots': shots,
      'cues': {'silence_start': -10, 'keep_msg': -9, 'camera_freeze': cut + 5, 'hard_black': cut, 'music_cut': cut},
      'audio': {'voiceGainDb': 0, 'musicGainDb': -12, 'events': ev, 'music': [{'t': round(t, 3), 'level': l} for t, l in mus], 'chords': chords,
                'heart': [[st['06'], st['08'], 66], [st['10'], st['12'], 70], [st['20'], cut, 84]], 'eerie': [[st['20'], cut - st['20']]]},
    }
    json.dump(tl, open(os.path.join(ROOT, 'config', f'timeline.ep02_{lang}.json'), 'w'), ensure_ascii=False, indent=1)
    return tl, shots

def fmt(t): return f"{int(t // 60)}:{t % 60:05.2f}"

def doc(i, tl, shots):
    lang = ('ru', 'en')[i]
    title = ('А ЧТО, ЕСЛИ… ВОДА ИСЧЕЗЛА СО ВСЕЙ ПЛАНЕТЫ?', 'WHAT IF… WATER DISAPPEARED FROM THE ENTIRE PLANET?')[i]
    md = [f'# {title}', '', f'Сценарий и разбивка на сцены — версия {lang.upper()} (16:9, 1920×1080, 30 fps). Длительность ролика: {fmt(tl["duration"])}.',
          '', 'Время указано по готовому видео (озвучка начинается после звонка будильника, +%.1f с).' % OFF, '']
    for s, sh in zip(S, shots):
        d = s['doc']; a = sh['start'] - OFF; b = sh['end'] - OFF
        md += [f"## Сцена {s['n']}. {s['title']}", '',
               f"1. **Номер сцены:** {s['n']}",
               f"2. **Время:** {fmt(sh['start'])} – {fmt(sh['end'])}",
               f"3. **Текст озвучки:** «{words_between(i, a, b) or '— (без текста, звук)'}»",
               f"4. **Что происходит:** {d['what']}",
               f"5. **Изображение:** {d['img']}",
               f"6. **Камера:** {d['cam']}",
               f"7. **Анимация и эффекты:** {d['fx']}",
               f"8. **Звуковые эффекты:** {', '.join(s['sfx'])}",
               f"9. **Музыка:** {d['music']}",
               f"10. **Переход:** {d['trans']}", '']
    os.makedirs(os.path.join(ROOT, '..', 'docs'), exist_ok=True)
    open(os.path.join(ROOT, '..', 'docs', f'EP02_scenario_{lang}.md'), 'w').write('\n'.join(md))

for i in (0, 1):
    tl, shots = build(i); doc(i, tl, shots)
    print(('ru', 'en')[i], len(shots), 'shots, duration', tl['duration'])
